import sys
import sys
sys.setrecursionlimit(10**6)

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.height = 0

def insert(root, value, depth, counter):
    if root is None:
        return Node(value), depth

    if value < root.value:
        root.left, new_depth = insert(root.left, value, depth + 1, counter)
    else:
        root.right, new_depth = insert(root.right, value, depth + 1, counter)

    return root, new_depth

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    values = list(map(int, data[1:1+n]))

    root = None
    counter = 0
    results = []

    for value in values:
        if root is None:
            root = Node(value)
            depth = 0
        else:
            root, depth = insert(root, value, 0, counter)

        counter += depth
        results.append(str(counter))

    sys.stdout.write('\n'.join(results))

if __name__ == "__main__":
    main()

