import sys

def solve():
    ratios = []
    for _ in range(12):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        n, d = map(int, line.split('/'))
        ratios.append((n, d))

    # Try all possible front sprocket pairs (u1, u2) where u1 < u2
    for u1 in range(1, 10001):
        for u2 in range(u1 + 1, 10001):
            # For each front sprocket, compute possible rear sprockets from ratios
            rear_candidates = []
            for n, d in ratios:
                # Rear sprocket v = u * d / n must be integer
                # Try both front sprockets
                v1_candidate = u1 * d / n
                v2_candidate = u2 * d / n
                candidates = []
                if v1_candidate.is_integer() and 1 <= v1_candidate <= 10000:
                    candidates.append(int(v1_candidate))
                if v2_candidate.is_integer() and 1 <= v2_candidate <= 10000:
                    candidates.append(int(v2_candidate))
                if not candidates:
                    break
                rear_candidates.append(candidates)
            else:
                # All ratios gave at least one candidate rear sprocket
                # Now we need to select exactly 6 distinct rear sprockets
                # that cover all ratios
                from itertools import product
                # Generate all combinations of choosing one candidate per ratio
                for combo in product(*rear_candidates):
                    rear_set = set(combo)
                    if len(rear_set) == 6:
                        # Verify all ratios are achievable with these sprockets
                        front_set = {u1, u2}
                        achievable = set()
                        for u in front_set:
                            for v in rear_set:
                                # Reduce fraction u/v to simplest form
                                from math import gcd
                                g = gcd(u, v)
                                n_simple = u // g
                                d_simple = v // g
                                achievable.add((n_simple, d_simple))
                        if all((n, d) in achievable for n, d in ratios):
                            # Output solution
                            rear_sorted = sorted(rear_set, reverse=True)
                            return f"{u1} {u2}\n{' '.join(map(str, rear_sorted))}"
    return "impossible"

if __name__ == "__main__":
    print(solve())

