import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)

    # Check if solution exists
    # We need at least 2 colors for n=2, and more generally need enough colors
    # Based on analysis: need k >= 2 and n <= k*(k-1)
    if k == 1 or n > k * (k - 1):
        print("NO")
        return

    print("YES")

    # Generate pairs using a systematic approach
    # We'll generate all possible valid pairs (b,g) with b != g
    # Then output them in an order satisfying adjacency constraints
    pairs = []
    for b in range(1, k + 1):
        for g in range(1, k + 1):
            if b != g:
                pairs.append((b, g))

    # We need exactly n pairs
    # Output first n pairs in a specific order to satisfy adjacency constraints
    # Strategy: alternate between two sequences to ensure b_i != b_{i+1} and g_i != g_{i+1}
    result = []

    # Use two indices to alternate
    idx1 = 0
    idx2 = k * (k - 1) // 2  # Start from middle-ish point for better alternation

    for i in range(n):
        if i % 2 == 0:
            result.append(pairs[idx1])
            idx1 = (idx1 + 1) % len(pairs)
        else:
            result.append(pairs[idx2])
            idx2 = (idx2 + 1) % len(pairs)

    # Verify adjacency constraints (sanity check)
    for i in range(n - 1):
        if result[i][0] == result[i + 1][0] or result[i][1] == result[i + 1][1]:
            # If constraints violated, use a more robust generation
            # Build sequence by ensuring each step changes both b and g
            result = []
            # Create a sequence where b cycles through colors and g follows a different pattern
            for i in range(n):
                b = (i % k) + 1
                g = ((i + 1) % k) + 1
                if b == g:
                    g = (g % k) + 1
                result.append((b, g))
            break

    for b, g in result:
        print(f"{b} {g}")

