import sys
import math

def prime_factors(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Step 1: Compute total prime factor counts
    total_factors = {}
    for num in arr:
        pf = prime_factors(num)
        for p, cnt in pf.items():
            total_factors[p] = total_factors.get(p, 0) + cnt

    # Step 2: Determine maximal possible GCD
    max_gcd = 1
    for p, cnt in total_factors.items():
        # Each prime p can contribute floor(cnt/n) to each element in final GCD
        power = cnt // n
        if power > 0:
            max_gcd *= p ** power

    # Step 3: Compute minimal operations
    operations = 0
    for num in arr:
        pf = prime_factors(num)
        for p, target_power in [(p, total_factors[p] // n) for p in total_factors if total_factors[p] // n > 0]:
            current = pf.get(p, 0)
            if current < target_power:
                operations += target_power - current

    print(f"{max_gcd} {operations}")

if __name__ == "__main__":
    main()

