import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    W, H = map(int, data[0].split())
    grid = [list(row) for row in data[1:]]

    # Find start position
    start = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'P':
                start = (i, j)
                break
        if start:
            break

    # BFS to explore safe reachable area
    visited = [[False] * W for _ in range(H)]
    queue = [start]
    visited[start[0]][start[1]] = True
    gold_count = 0

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.pop(0)

        # Collect gold if present
        if grid[r][c] == 'G':
            gold_count += 1

        # Check if any adjacent cell is a trap
        has_adjacent_trap = False
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if grid[nr][nc] == 'T':
                    has_adjacent_trap = True
                    break

        # If adjacent to trap, don't explore further from this cell
        if has_adjacent_trap:
            continue

        # Explore neighbors
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                if grid[nr][nc] != '#':  # Not a wall
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    print(gold_count)

if __name__ == "__main__":
    solve()

