            if (a[i] > a[j]) {
                original_swaps++;
            }
        }
    }

    // Step 2: Try all swaps and compute best improvement
    int best_improvement = 0;
    long long ways = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            // Compute improvement for swapping a[i] and a[j]
