            // Handle the pair (i, j) itself
            if (a[i] > a[j]) {
                improvement += 1;
            } else {
                improvement -= 1;
            }

            // Compare with best
            if (improvement > best_improvement) {
                best_improvement = improvement;
                ways = 1;
            } else if (improvement == best_improvement) {
                ways++;
            }
        }
    }

    // Step 3: Output results
    int min_swaps = original_swaps - best_improvement;
    cout << min_swaps << " " << ways << endl;

    return 0;
