import sys

def insertion_sort_swaps(arr):
    """Return number of swaps performed by insertion sort on array."""
    n = len(arr)
    swaps = 0
    for i in range(1, n):
        j = i
        while j > 0 and arr[j] < arr[j-1]:
            arr[j], arr[j-1] = arr[j-1], arr[j]
            swaps += 1
            j -= 1
    return swaps

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    perm = list(map(int, data[1:1+n]))

    # Step 1: Compute original swaps
    original_arr = perm[:]
    original_swaps = insertion_sort_swaps(original_arr)

    # Step 2: For each pair (i, j) with i < j, compute swaps after swapping
    min_swaps = float('inf')
    count = 0

    # Precompute inversions for each element
    # inv_before[x] = number of elements before position x that are greater than perm[x]
    # inv_after[x] = number of elements after position x that are less than perm[x]
    inv_before = [0]*n
    inv_after = [0]*n
    for i in range(n):
        for j in range(i):
            if perm[j] > perm[i]:
                inv_before[i] += 1
        for j in range(i+1, n):
            if perm[j] < perm[i]:
                inv_after[i] += 1

    # For each pair (i, j) with i < j
    for i in range(n):
        for j in range(i+1, n):
            # Compute change in swaps when swapping perm[i] and perm[j]
            # Original inversions involving i and j
            orig_inv_i = inv_before[i] + inv_after[i]
            orig_inv_j = inv_before[j] + inv_after[j]

            # After swapping, compute new inversions
            # For element originally at i (now at j):
            #   inversions with elements between i and j
            new_inv_i = 0
            for k in range(i+1, j):
                if perm[k] > perm[i]:
                    new_inv_i += 1
                if perm[k] < perm[j]:
                    new_inv_i += 1
            # Plus inversions with elements outside [i, j]
            # Elements before i: compare with perm[j] (now at i)
            for k in range(i):
                if perm[k] > perm[j]:
                    new_inv_i += 1
            # Elements after j: compare with perm[i] (now at j)
            for k in range(j+1, n):
                if perm[k] < perm[i]:
                    new_inv_i += 1

            # For element originally at j (now at i):
            new_inv_j = 0
            for k in range(i+1, j):
                if perm[k] < perm[j]:
                    new_inv_j += 1
                if perm[k] > perm[i]:
                    new_inv_j += 1
            # Elements before i: compare with perm[j] (now at i)
            for k in range(i):
                if perm[k] < perm[j]:
                    new_inv_j += 1
            # Elements after j: compare with perm[i] (now at j)
            for k in range(j+1, n):
                if perm[k] > perm[i]:
                    new_inv_j += 1

            # Total swaps after swap = original_swaps - (orig_inv_i + orig_inv_j) + (new_inv_i + new_inv_j)
            # But need to adjust for the fact that i and j themselves form an inversion if perm[i] > perm[j]
            adjustment = 1 if perm[i] > perm[j] else -1
            new_swaps = original_swaps - (orig_inv_i + orig_inv_j) + (new_inv_i + new_inv_j) + adjustment

            if new_swaps < min_swaps:
                min_swaps = new_swaps
                count = 1
            elif new_swaps == min_swaps:
                count += 1

    print(f"{min_swaps} {count}")

if __name__ == "__main__":
    solve()

