def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0])
    lines = data[1:]

    # Stack to track events that have happened (not dreamt)
    event_stack = []
    # Set to quickly check if an event is currently in the stack
    event_set = set()

    output = []

    for line in lines:
        parts = line.split()
        if not parts:
            continue

        if parts[0] == 'E':
            # Event happens
            event = parts[1]
            event_stack.append(event)
            event_set.add(event)

        elif parts[0] == 'D':
            # Dream: remove last r events
            r = int(parts[1])
            for _ in range(r):
                if event_stack:
                    event_set.remove(event_stack.pop())

        elif parts[0] == 'S':
            # Scenario
            k = int(parts[1])
            scenario_events = parts[2:]

            # Check if scenario is consistent with current reality
            consistent = True
            for ev in scenario_events:
                if ev.startswith('!'):
                    # Event should NOT have happened
                    if ev[1:] in event_set:
                        consistent = False
                        break
                else:
                    # Event should have happened
                    if ev not in event_set:
                        consistent = False
                        break

            if consistent:
                output.append("Yes")
                continue

            # If not consistent, check if adding a dream before scenario makes it consistent
            # We need to find smallest r such that removing last r events makes scenario consistent
            min_r = None

            # Try all possible r from 1 to len(event_stack)
            for r in range(1, len(event_stack) + 1):
