#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 9;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // Count frequencies
    map<int, int> freq;
    for (int x : a) {
        freq[x]++;
    }

    // Total permutations with duplicates
    long long total = 1;
    for (auto &p : freq) {
        for (int i = 1; i <= p.second; i++) {
            total = (total * i) % MOD;
        }
    }

    // Count permutations with at least one sorted element
    long long with_sorted = 0;

    // For each unique value, count permutations where it appears as sorted
    for (auto &p : freq) {
        int val = p.first;
        int cnt = p.second;

        // Count numbers strictly less than val
        int less = 0;
        for (auto &q : freq) {
            if (q.first < val) less += q.second;
        }

        // Count numbers strictly greater than val
        int greater = 0;
        for (auto &q : freq) {
            if (q.first > val) greater += q.second;
        }

        // For each occurrence of this value, we need to place it such that:
        // - All elements to its left are ≤ val
        // - All elements to its right are ≥ val
        // But since we have duplicates, we need to handle carefully

        // We'll use inclusion-exclusion principle
        // Let's count permutations where at least one occurrence of this value is sorted

        // Total positions for this value: n
        // Valid positions: positions where there are at least 'less' elements to the left
        // and at least 'greater' elements to the right

        // Number of valid positions for a sorted occurrence of this value
        int valid_positions = max(0, n - less - greater);

        if (valid_positions > 0) {
            // Arrange the remaining n-1 elements (with duplicates)
            long long ways = 1;
            map<int, int> temp_freq = freq;
            temp_freq[val]--;
            if (temp_freq[val] == 0) temp_freq.erase(val);

            for (auto &q : temp_freq) {
                for (int i = 1; i <= q.second; i++) {
                    ways = (ways * i) % MOD;
                }
            }

            // Multiply by number of valid positions
            ways = (ways * valid_positions) % MOD;

            // Add to total with_sorted
            with_sorted = (with_sorted + ways) % MOD;
        }
    }

    // Apply inclusion-exclusion: total - with_sorted
    long long result = (total - with_sorted + MOD) % MOD;

    cout << result << endl;

    return 0;
}

