import sys
import sys
sys.setrecursionlimit(300000)

def find(x, parent):
    if parent[x] != x:
        parent[x] = find(parent[x], parent)
    return parent[x]

def union(x, y, parent, rank):
    rx, ry = find(x, parent), find(y, parent)
    if rx == ry:
        return False
    if rank[rx] < rank[ry]:
        parent[rx] = ry
    elif rank[rx] > rank[ry]:
        parent[ry] = rx
    else:
        parent[ry] = rx
        rank[rx] += 1
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))
    capacities = [int(next(it)) for _ in range(n)]

    parent = list(range(n))
    rank = [0] * n
    existing_edges = 0
    redundant_edges = 0

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        if not union(u, v, parent, rank):
            redundant_edges += 1
        else:
            existing_edges += 1

    components = len(set(find(i, parent) for i in range(n)))
    needed_edges = components - 1

    if needed_edges > k:
        print("no")
        return

    free_sockets = [capacities[i] for i in range(n)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        free_sockets[u] -= 1
        free_sockets[v] -= 1

    total_free = sum(free_sockets)
    if total_free < 2 * needed_edges:
        print("no")
        return

    if redundant_edges + (k - needed_edges) >= needed_edges:
        print("yes")
    else:
        print("no")

if __name__ == "__main__":
    main()

