import sys
import math

def cross(o, a, b):
    """Cross product (a-o) x (b-o)"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    """Andrew's monotone chain algorithm"""
    points = sorted(set(points))
    if len(points) <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def collinear(a, b, c):
    """Check if three points are collinear"""
    return cross(a, b, c) == 0

def min_lines_on_convex_polygon(points):
    """Find minimum lines covering points on convex polygon boundary"""
    hull = convex_hull(points)
    m = len(hull)
    if m <= 2:
        return 1

    # DP array: dp[i][j] = min lines covering points from i to j (inclusive)
    dp = [[float('inf')] * m for _ in range(m)]

    # Initialize for single points and adjacent pairs
    for i in range(m):
        dp[i][i] = 1
        if i + 1 < m:
            dp[i][i+1] = 1

    # Fill DP for longer segments
    for length in range(2, m):
        for i in range(m - length):
            j = i + length
            # Try all possible splits
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])
