def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        print("begin repairs")
        return

    Y, X, x_init = map(int, data[0].split())
    grid = data[1:]

    # Find castle position
    castle_y = castle_x = -1
    for y in range(Y):
        for x in range(X):
            if grid[y][x] == '@':
                castle_y, castle_x = y, x
                break
        if castle_y != -1:
            break

    # DP table: dp[y][x] = number of ways to reach (y, x)
    dp = [[0] * X for _ in range(Y)]
    dp[Y-1][x_init] = 1  # start position

    # Process from bottom to top
    for y in range(Y-1, -1, -1):
        for x in range(X-1, -1, -1):
            if grid[y][x] == '#':
                continue
            if dp[y][x] == 0:
                continue

            # Move north (lower sails)
            if y > 0 and grid[y-1][x] != '#':
                dp[y-1][x] = (dp[y-1][x] + dp[y][x]) % MOD

            # Handle currents
            if grid[y][x] == '>':
                nx = x + 1
                if nx < X and grid[y][nx] != '#':
                    dp[y][nx] = (dp[y][nx] + dp[y][x]) % MOD
            elif grid[y][x] == '<':
                nx = x - 1
                if nx >= 0 and grid[y][nx] != '#':
                    dp[y][nx] = (dp[y][nx] + dp[y][x]) % MOD
            elif grid[y][x] == '~':
                # Open sea: can move east or west by retracting sails
