#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        vector<int> x(n), y(n);
        for (int i = 0; i < n; i++) cin >> x[i];
        for (int i = 0; i < n; i++) cin >> y[i];

        // Sort points by x-coordinate
        vector<pair<int, int>> points(n);
        for (int i = 0; i < n; i++) points[i] = {x[i], y[i]};
        sort(points.begin(), points.end());

        // Extract sorted x-coordinates
        vector<int> xs(n);
        for (int i = 0; i < n; i++) xs[i] = points[i].first;

        // Precompute max points covered by a single platform ending at each position
        vector<int> cover(n), max_left(n), max_right(n);

        // Two-pointer to compute cover[i] = points covered by platform ending at i
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (xs[i] - xs[j] > k) j++;
            cover[i] = i - j + 1;
        }

        // Prefix max: max_left[i] = max cover ending at or before i
        max_left[0] = cover[0];
        for (int i = 1; i < n; i++) {
            max_left[i] = max(max_left[i-1], cover[i]);
        }

        // Suffix max: max_right[i] = max cover starting at or after i
        max_right[n-1] = cover[n-1];
        for (int i = n-2; i >= 0; i--) {
            max_right[i] = max(max_right[i+1], cover[i]);
        }

        // Try all splits between platforms
        int ans = 0;
        for (int i = 0; i < n; i++) {
            // Platform 1 covers points up to i, platform 2 covers points after i
            int left_cover = max_left[i];
            int right_cover = (i+1 < n) ? max_right[i+1] : 0;
            ans = max(ans, left_cover + right_cover);

            // Also consider case where platforms overlap or one platform covers all
            ans = max(ans, cover[i]);
        }

        // Edge case: two platforms covering disjoint intervals
        j = 0;
        for (int i = 0; i < n; i++) {
            while (xs[i] - xs[j] > k) j++;
            // Platform covers [j, i], find best non-overlapping platform after i
            if (i+1 < n) {
                ans = max(ans, (i - j + 1) + max_right[i+1]);
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

