import sys
import math
MOD = 10**9 + 7

def factorize(m):
    factors = {}
    temp = m
    for i in range(2, int(math.isqrt(temp)) + 1):
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def nCr(n, r, fact, inv_fact):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    N = int(input_data[0])
    M = int(input_data[1])

    if M == 1:
        print(1)
        return

    factors = factorize(M)

    max_exp = max(factors.values()) if factors else 0
    max_n = N + max_exp

    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    result = 1
    for exp in factors.values():
        ways = nCr(N + exp - 1, exp, fact, inv_fact)
        result = result * ways % MOD

    print(result)

if __name__ == "__main__":
    main()

