import sys

def solve() -> None:
    data = sys.stdin.read().strip().split('\n')
    if len(data) < 2:
        print('corrupted')
        return
    I, O = data[0], data[1]

    # Find positions of + and - in I
    plus_pos = [i for i, ch in enumerate(I) if ch == '+']
    minus_pos = [i for i, ch in enumerate(I) if ch == '-']

    # If no + or -, trivial case
    if not plus_pos and not minus_pos:
        if I == O:
            print('<any> <any>')
        else:
            print('corrupted')
        return

    # Helper to check if a mapping works
    def check_mapping(plus_enc: str, minus_enc: str) -> bool:
        ptr_i, ptr_o = 0, 0
        while ptr_i < len(I) and ptr_o < len(O):
            if I[ptr_i] == '+':
                if not O.startswith(plus_enc, ptr_o):
                    return False
                ptr_o += len(plus_enc)
            elif I[ptr_i] == '-':
                if not O.startswith(minus_enc, ptr_o):
                    return False
                ptr_o += len(minus_enc)
            else:
                if O[ptr_o] != I[ptr_i]:
                    return False
                ptr_o += 1
            ptr_i += 1
        return ptr_i == len(I) and ptr_o == len(O)

    # Generate all possible encodings
    results = []
    n = len(O)

    # Try all possible lengths for plus_enc and minus_enc
    for lp in range(n + 1):
        for lm in range(n + 1):
            plus_enc = O[:lp] if lp > 0 else ''
            minus_enc = O[:lm] if lm > 0 else ''

            # Quick length check
            expected_len = (len(I) - len(plus_pos) - len(minus_pos))
            expected_len += lp * len(plus_pos) + lm * len(minus_pos)
            if expected_len != len(O):
                continue

            if check_mapping(plus_enc, minus_enc):
                plus_str = '<empty>' if lp == 0 else ('<any>' if plus_enc == '' and lp > 0 else plus_enc)
                minus_str = '<empty>' if lm == 0 else ('<any>' if minus_enc == '' and lm > 0 else minus_enc)
                # Handle <any> properly
                if plus_str == '<any>':
                    plus_str = '<any>'
                if minus_str == '<any>':
                    minus_str = '<any>'
                results.append((plus_str, minus_str))

    # Remove duplicates
    results = list(dict.fromkeys(results))

    if not results:
        print('corrupted')
    else:
        for p, m in results:
            print(p, m)

if __name__ == '__main__':
    solve()

