import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(row) for row in data[1:1+n]]

    # First pass: place 'E' greedily on land cells that are not adjacent to existing 'E'
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                # Check if adjacent to existing 'E'
                adjacent_to_E = False
                for di, dj in [(0,1),(1,0),(0,-1),(-1,0)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 'E':
                        adjacent_to_E = True
                        break
                if not adjacent_to_E:
                    # Check if placing 'E' here would violate adjacency with other potential placements
                    can_place = True
                    for di, dj in [(0,1),(1,0),(0,-1),(-1,0)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                            # Check if this neighbor would become isolated if we place 'E' here
                            neighbor_has_adjacent = False
                            for ddi, ddj in [(0,1),(1,0),(0,-1),(-1,0)]:
                                nni, nnj = ni + ddi, nj + ddj
                                if 0 <= nni < n and 0 <= nnj < m:
                                    if (nni == i and nnj == j) or grid[nni][nnj] == 'E':
                                        neighbor_has_adjacent = True
                                        break
                            if not neighbor_has_adjacent:
                                can_place = False
                                break
                    if can_place:
                        grid[i][j] = 'E'

    # Second pass: ensure all land cells are covered
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                covered = False
                for di, dj in [(0,1),(1,0),(0,-1),(-1,0)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 'E':
                        covered = True
                        break
                if not covered:
                    # Place 'E' in this cell
                    grid[i][j] = 'E'

    # Output
    for row in grid:
        print(''.join(row))

if __name__ == "__main__":
    solve()

