def count_triangles(n):
    count = 0
    for a in range(1, n + 1):
        for b in range(a, n + 1):
            c_squared = a * a + b * b
            c = int(c_squared ** 0.5)
            if c <= n and c * c == c_squared:
                count += 1
    return count

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    print(count_triangles(n))

