import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = [list(row) for row in data[1:]]

    # Find all white pixel positions
    whites = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'w':
                whites.append((i, j))

    if not whites:
        print(-1)
        return

    # Find bounding box of whites
    min_r = min(w[0] for w in whites)
    max_r = max(w[0] for w in whites)
    min_c = min(w[1] for w in whites)
    max_c = max(w[1] for w in whites)

    # Determine possible square frame size
    width = max(max_r - min_r, max_c - min_c) + 1

    # Check if all whites lie on a square frame of this size
    # Try all possible top-left corners within bounds
    best_frame = None
    best_grid = None

    for top in range(n - width + 1):
        for left in range(m - width + 1):
            bottom = top + width - 1
            right = left + width - 1

            # Check if all whites are on the border of this square
            valid = True
            for r, c in whites:
                if not (r == top or r == bottom or c == left or c == right):
                    valid = False
                    break
                if not (top <= r <= bottom and left <= c <= right):
                    valid = False
                    break
            if not valid:
                continue

            # Check that no white is missing from the border
            # Create candidate frame
            candidate = [row[:] for row in grid]
            frame_ok = True
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    if r == top or r == bottom or c == left or c == right:
                        if candidate[r][c] == 'w':
                            continue  # already white
                        elif candidate[r][c] == '.':
                            candidate[r][c] = '+'
                        else:
                            frame_ok = False
                            break
                    else:
                        if candidate[r][c] == 'w':
                            frame_ok = False  # white inside frame
                            break
                if not frame_ok:
                    break

            if frame_ok:
                best_frame = (top, left, width)
                best_grid = candidate
                break
        if best_frame:
            break

    if best_grid:
        for row in best_grid:
            print(''.join(row))
    else:
        print(-1)

if __name__ == "__main__":
    solve()

