import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    x = list(map(int, data[1:1+N]))

    # Create difference array of face-up positions
    diff = [0] * (N + 2)  # 1-indexed with extra padding
    for i in range(N):
        diff[x[i]] ^= 1

    # We need to find minimum operations to make all diff entries 0
    # Operation: flip p consecutive cards where p is prime >= 3
    # This corresponds to toggling diff[l] and diff[l+p] for some l

    # Build list of primes >= 3 up to max needed (10^7 + some margin)
    MAX_VAL = 10**7 + 100
    is_prime = [True] * (MAX_VAL + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for i in range(2, MAX_VAL + 1):
        if is_prime[i]:
            if i >= 3:
                primes.append(i)
            for j in range(i*i, MAX_VAL + 1, i):
                is_prime[j] = False

    # Greedy matching: pair up 1s in diff using prime gaps
    ones = [i for i in range(1, MAX_VAL + 1) if diff[i]]
    if not ones:
        print(0)
        return

    # DP approach: dp[i] = min ops to clear first i ones
    m = len(ones)
    dp = [10**9] * (m + 1)
    dp[0] = 0

    for i in range(m):
        if dp[i] == 10**9:
            continue
        # Option 1: clear ones[i] alone with prime 3 (if possible)
        # Actually need to check if we can clear a single 1
        # A single 1 at position pos can be cleared by operation at pos with p=3
        # This creates another 1 at pos+3, so we need to handle that
        # Instead, we'll pair ones

        # Try to pair ones[i] with ones[j] for j > i
        for j in range(i+1, m):
            gap = ones[j] - ones[i]
            # Check if gap can be expressed as sum of primes >= 3
            # Since we can chain operations, we need min number of primes summing to gap
            # This is classic prime sum problem: min number of primes summing to n
            # With primes >= 3, and we can use same prime multiple times

            # Precompute min primes needed for gaps up to max gap
            max_gap = ones[-1] - ones[0]
