import sys
import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def normalize_vector(x, y):
    """Normalize a vector to a canonical form for direction."""
    if x == 0 and y == 0:
        return (0, 0)
    g = gcd(x, y)
    x //= g
    y //= g
    if x < 0 or (x == 0 and y < 0):
        x, y = -x, -y
    return (x, y)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    points = []
    idx = 1
    for i in range(n):
        x = int(data[idx]); y = int(data[idx+1])
        idx += 2
        points.append((x, y))

    # Special case: n == 1
    if n == 1:
        print(-1)
        return

    # Compute all midpoints between pairs of points
    midpoints = []
    for i in range(n):
        for j in range(i+1, n):
            mx = points[i][0] + points[j][0]
            my = points[i][1] + points[j][1]
            midpoints.append((mx, my))

    # For each midpoint, compute direction vectors from origin to midpoint
    # A line through origin is good if it's perpendicular to some midpoint vector
    # Because projection symmetry means the midpoint of each pair lies on a line perpendicular to the projection line
    dir_counts = defaultdict(int)
    for mx, my in midpoints:
