            return
        # Direction perpendicular to (mx, my)
        perp_x = -my
        perp_y = mx
        norm = normalize_vector(perp_x, perp_y)
        dir_counts[norm] += 1

    # Count directions that appear at least n/2 times
    # Each such direction corresponds to a good line
    required = n // 2
    count = 0
    for cnt in dir_counts.values():
        if cnt >= required:
            count += 1

    if count == 0:
        print(0)
    else:
        print(count)

if __name__ == "__main__":
    solve()

