    # We'll try to 3-color the complement graph
    # In complement graph, edges exist where original graph has no edge
    # We need to check if complement is bipartite with 3 independent sets

    # Build adjacency for complement (only for checking, not full construction)
    # Instead, we can think: original graph must be complete tripartite
    # So each vertex must be connected to all vertices not in its own part

    # First, find a vertex with smallest degree as candidate for part 1
    min_deg_vertex = min(range(n), key=lambda i: len(adj[i]))

    # Vertices not connected to min_deg_vertex must be in same part as it
    part1_set = set([min_deg_vertex])
    for v in range(n):
        if v != min_deg_vertex and v not in adj[min_deg_vertex]:
            part1_set.add(v)

    # Remaining vertices are in parts 2 and 3
    remaining = [v for v in range(n) if v not in part1_set]
    if not remaining:
        print(-1)
        return

