    if i < 0 or i >= r or j < 0 or j >= c:
        return
    if visited[i][j] or grid[i][j] != 'L':
        return
    visited[i][j] = True
    dfs(grid, visited, i+1, j, r, c)
    dfs(grid, visited, i-1, j, r, c)
    dfs(grid, visited, i, j+1, r, c)
    dfs(grid, visited, i, j-1, r, c)

def count_islands(grid, r, c):
    """Count islands in current grid configuration"""
    visited = [[False]*c for _ in range(r)]
    islands = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'L' and not visited[i][j]:
                islands += 1
                dfs(grid, visited, i, j, r, c)
    return islands

def backtrack(grid, r, c, i, j):
    """Backtrack to try all cloud assignments"""
    if i == r:
        return count_islands(grid, r, c)

    next_i = i
    next_j = j + 1
    if next_j == c:
        next_i = i + 1
        next_j = 0

    if grid[i][j] != 'C':
        return backtrack(grid, r, c, next_i, next_j)

    # Try assigning cloud as water
    grid[i][j] = 'W'
    water_result = backtrack(grid, r, c, next_i, next_j)

    # Try assigning cloud as land
    grid[i][j] = 'L'
    land_result = backtrack(grid, r, c, next_i, next_j)

    # Restore cloud
    grid[i][j] = 'C'

    return min(water_result, land_result)

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    r, c = map(int, data[0].split())
    grid = [list(row.strip()) for row in data[1:]]

    # If all cells are clouds, minimum islands is 0
    all_clouds = True
    for i in range(r):
        for j in range(c):
            if grid[i][j] != 'C':
                all_clouds = False
                break
        if not all_clouds:
            break

    if all_clouds:
        print(0)
        return

    result = backtrack(grid, r, c, 0, 0)
    print(result)

if __name__ == "__main__":
    main()

