import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    words = data[1:1+n]
    start, end = words[0], words[1]
    dictionary = set(words)

    # If start == end, no steps needed
    if start == end:
        print("0\n0")
        return

    # BFS without any added word
    def bfs(available_words):
        if start not in available_words or end not in available_words:
            return float('inf')
        q = deque([(start, 0)])
        visited = {start}
        while q:
            word, dist = q.popleft()
            if word == end:
                return dist
            # Generate neighbors
            chars = list(word)
            for i in range(len(chars)):
                original = chars[i]
                for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                    if c == original:
                        continue
                    chars[i] = c
                    new_word = ''.join(chars)
                    if new_word in available_words and new_word not in visited:
                        visited.add(new_word)
                        q.append((new_word, dist + 1))
                chars[i] = original
        return float('inf')

    original_steps = bfs(dictionary)

    # If already reachable, try to improve
    best_word = "0"
    best_steps = original_steps

    # Consider all possible words of same length
    word_len = len(start)
    all_letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Generate candidate words to add
    candidates = set()
    # Candidates are words that differ by one letter from any word in dictionary
    for word in dictionary:
        chars = list(word)
        for i in range(word_len):
            original = chars[i]
            for c in all_letters:
                if c == original:
                    continue
                chars[i] = c
                new_word = ''.join(chars)
                if new_word not in dictionary:
                    candidates.add(new_word)
            chars[i] = original

    # Also consider words that differ by one letter from start or end
    for base in [start, end]:
        chars = list(base)
        for i in range(word_len):
            original = chars[i]
            for c in all_letters:
                if c == original:
                    continue
                chars[i] = c
                new_word = ''.join(chars)
                if new_word not in dictionary:
                    candidates.add(new_word)
            chars[i] = original

    # Evaluate each candidate
    for candidate in sorted(candidates):
        new_dict = dictionary | {candidate}
        steps = bfs(new_dict)
        if steps < best_steps:
            best_steps = steps
            best_word = candidate
            # Early stop if we found minimum possible steps (1 if adjacent)
            if best_steps == 1:
                break

    # Output
    if best_word == "0":
        if original_steps == float('inf'):
            print("0\n-1")
        else:
            print(f"0\n{original_steps}")
    else:
        print(f"{best_word}\n{best_steps}")

if __name__ == "__main__":
    solve()

