import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    q = int(next(it))
    queries = [int(next(it)) for _ in range(q)]

    # Precompute all possible sums using at most k bills of at most 2 denominations
    # We'll store for each sum the minimum number of bills
    max_sum = max(queries)
    INF = 10**9
    dp = [INF] * (max_sum + 1)
    dp[0] = 0

    # Try all pairs of denominations (including same denomination twice for single denomination case)
    for i in range(n):
        for j in range(i, n):
            d1, d2 = a[i], a[j]
            # Generate all combinations with at most k bills
            for cnt1 in range(k + 1):
                if cnt1 * d1 > max_sum:
                    break
                sum1 = cnt1 * d1
                if d1 == d2:
                    # Single denomination case
                    if dp[sum1] > cnt1:
                        dp[sum1] = cnt1
                    continue
                # Two denominations
                for cnt2 in range(k + 1 - cnt1):
                    total = sum1 + cnt2 * d2
                    if total > max_sum:
                        break
                    bills = cnt1 + cnt2
                    if bills > k:
                        break
                    if dp[total] > bills:
                        dp[total] = bills

    # Answer queries
    out_lines = []
    for x in queries:
        if x <= max_sum and dp[x] != INF and dp[x] <= k:
            out_lines.append(str(dp[x]))
        else:
            out_lines.append("-1")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

