def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list and compute in-degree
    adj = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    edges = []
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        edges.append((a, b))
        adj[a].append(b)
        indeg[b] += 1

    # Topological sort using Kahn's algorithm
    from collections import deque
    q = deque()
    for i in range(1, n + 1):
        if indeg[i] == 0:
            q.append(i)

    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    # If not all nodes are in topo order, there's a cycle
    if len(topo) != n:
        # Strongly Connected Components (SCC) condensation
        from sys import setrecursionlimit
        setrecursionlimit(300000)

        # Kosaraju's algorithm
        g = [[] for _ in range(n + 1)]
        rg = [[] for _ in range(n + 1)]
        for a, b in edges:
            g[a].append(b)
            rg[b].append(a)

        visited = [False] * (n + 1)
        order = []

        def dfs1(u):
            visited[u] = True
            for v in g[u]:
                if not visited[v]:
                    dfs1(v)
            order.append(u)

        for i in range(1, n + 1):
            if not visited[i]:
                dfs1(i)

        comp = [0] * (n + 1)
        cur = 0

        def dfs2(u):
            comp[u] = cur
            for v in rg[u]:
                if comp[v] == 0:
                    dfs2(v)

        for u in reversed(order):
            if comp[u] == 0:
                cur += 1
                dfs2(u)

        # Build condensation DAG
        scc_adj = [set() for _ in range(cur + 1)]
        scc_indeg = [0] * (cur + 1)
        for a, b in edges:
            ca, cb = comp[a], comp[b]
            if ca != cb and cb not in scc_adj[ca]:
                scc_adj[ca].add(cb)
                scc_indeg[cb] += 1

        # Count sources and sinks in condensation DAG
        sources = sum(1 for i in range(1, cur + 1) if scc_indeg[i] == 0)
        sinks = sum(1 for i in range(1, cur + 1) if len(scc_adj[i]) == 0)

        # Minimum edges to make condensation DAG strongly connected
        if cur == 1:
            print(0)
        else:
            print(max(sources, sinks))
    else:
        # DAG case: longest path in DAG
        dp = [0] * (n + 1)
        for u in topo:
