import sys

def solve():
    A, B, C, D, E, F = map(int, sys.stdin.read().split())
    max_water = F // 100 * 100
    water_ops = [100 * A, 100 * B]
    sugar_ops = [C, D]

    possible_waters = set()
    for i in range(max_water // water_ops[0] + 1):
        for j in range(max_water // water_ops[1] + 1):
            water = i * water_ops[0] + j * water_ops[1]
            if 0 < water <= max_water:
                possible_waters.add(water)

    possible_sugars = set()
    max_sugar = F
    for i in range(max_sugar // sugar_ops[0] + 1):
        for j in range(max_sugar // sugar_ops[1] + 1):
            sugar = i * sugar_ops[0] + j * sugar_ops[1]
            if sugar <= max_sugar:
                possible_sugars.add(sugar)

    best_total, best_sugar = 100 * A, 0
    best_density = 0.0

    for water in possible_waters:
        max_dissolved = min(water // 100 * E, F - water)
        for sugar in possible_sugars:
            if sugar == 0:
                continue
            if sugar > max_dissolved:
                break
            total = water + sugar
            if total > F:
                break
            density = (100 * sugar) / total if total > 0 else 0.0
            if density > best_density or (abs(density - best_density) < 1e-12 and total > best_total):
                best_density = density
                best_total = total
                best_sugar = sugar

    print(f"{best_total} {best_sugar}")

if __name__ == "__main__":
    solve()

