import sys

def read_input():
    data = sys.stdin.read().strip().split()
    p = int(data[0])
    seq = list(map(int, data[1:1 + p]))
    return p, seq

def find_triple_correlation(p, seq):
    min_threshold = (p + 39) // 40 + 1  # ceil(p/40) + 1
    best = None  # (start_idx, a, n, b, m, c)

    # Try all possible a, b, c, n, m
    for a in range(10):
        for b in range(10):
            for c in range(10):
                for n in range(1, p):
                    for m in range(1, p - n):
                        # Check if this pattern meets the threshold
                        count = 0
                        first_occurrence = None

                        # Check condition 1: a followed n later by b implies c m after b
                        valid = True
                        for i in range(p - n - m):
                            if seq[i] == a and seq[i + n] == b:
                                if i + n + m >= p:
                                    continue  # c would be beyond sequence
                                if seq[i + n + m] != c:
                                    valid = False
                                    break
                                count += 1
                                if first_occurrence is None:
                                    first_occurrence = i

                        if not valid:
                            continue

                        # Check condition 2: b followed m later by c implies a n before b
                        for i in range(n, p - m):
                            if seq[i] == b and seq[i + m] == c:
                                if i - n < 0:
                                    continue  # a would be before sequence
                                if seq[i - n] != a:
                                    valid = False
                                    break

                        if not valid:
                            continue

                        # Check condition 3: a followed n+m later by c implies b n after a
                        for i in range(p - n - m):
                            if seq[i] == a and seq[i + n + m] == c:
                                if i + n >= p:
                                    continue  # b would be beyond sequence
                                if seq[i + n] != b:
                                    valid = False
                                    break

                        if not valid:
                            continue

                        # Check threshold
                        if count >= min_threshold:
                            candidate = (first_occurrence, a, n, b, m, c)
                            if best is None:
                                best = candidate
                            else:
                                # Compare: earliest start, then smaller n, then smaller m
                                if first_occurrence < best[0]:
                                    best = candidate
                                elif first_occurrence == best[0]:
                                    if n < best[2]:
                                        best = candidate
                                    elif n == best[2] and m < best[4]:
                                        best = candidate

    return best

def main():
    p, seq = read_input()
    result = find_triple_correlation(p, seq)
    if result:
        start_idx, a, n, b, m, c = result
        print(f"triple correlation {a}({n}){b}({m}){c} found")
    else:
        print("random sequence")

if __name__ == "__main__":
    main()

