    k = len(A)
    C = [[0]*k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            for l in range(k):
                C[i][j] = (C[i][j] + A[i][l] * B[l][j]) % MOD
    return C

def matrix_pow(M, power):
    k = len(M)
    result = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    while power > 0:
        if power & 1:
            result = matrix_mult(result, M)
        M = matrix_mult(M, M)
        power >>= 1
    return result

