        valid = True
        for i in range(n-1):
            if ((mask >> i) & 1) and ((mask >> (i+1)) & 1):
                # Check knight attacks in same column (vertical 2x3 rectangle)
                # For n <= 4, knights in same column can attack if they're 2 apart
                # Actually knights attack through 2x3 rectangles, so same column knights
                # can attack if they have exactly one empty row between them
                # Let's check all pairs with distance 2
