        if valid:
            all_states.append(mask)

    # Actually, let's properly check for attacks within same column
    # Knight attacks through 2x3 rectangle: positions (r1,c) and (r2,c) can attack
    # if |r1-r2| = 2 and there's exactly 1 row between them
    # But wait, that's for different columns. For same column, they need to be
    # in opposite corners of 2x3 rectangle, which requires different columns.
    # So knights in same column cannot attack each other directly.
    # The attack condition is: two knights at (r1,c1) and (r2,c2) can attack if
    # |r1-r2| = 2 and |c1-c2| = 1 OR |r1-r2| = 1 and |c1-c2| = 2
    # So for adjacent columns, we need to check these patterns.

    # Let's regenerate states properly
    all_states = []
    for mask in range(1 << n):
        # Check if knights in same mask attack each other (they shouldn't since same column)
        # Actually same column knights with |r1-r2| = 2 and |c1-c2| = 0 don't match attack pattern
        # So all same-column configurations are valid
        all_states.append(mask)

    k = len(all_states)
    state_index = {mask: i for i, mask in enumerate(all_states)}

    # Build transition matrix
    T = [[0]*k for _ in range(k)]
    for i, mask1 in enumerate(all_states):
        for j, mask2 in enumerate(all_states):
            valid = True
            # Check if mask1 (column c) and mask2 (column c+1) have attacking knights
            for r1 in range(n):
                if not (mask1 >> r1) & 1:
                    continue
                for r2 in range(n):
                    if not (mask2 >> r2) & 1:
                        continue
                    dr = abs(r1 - r2)
                    # Adjacent columns, so dc = 1
                    if (dr == 2 and 1 == 1) or (dr == 1 and 1 == 2):
                        # Actually the second condition should be dr=1 and dc=2
                        # But dc is fixed as 1 for adjacent columns
                        # So only dr=2, dc=1 pattern matters for adjacent columns
                        if dr == 2:
                            valid = False
                            break
                    # Also check dr=1, dc=2 - but that requires columns 2 apart
                    # So not relevant for adjacent columns
                if not valid:
                    break
            if valid:
                T[i][j] = 1

    # Initial vector: all states are valid for first column
    vec = [1]*k

    if m > 1:
        # Compute T^(m-1)
