import sys
MOD = 10**9 + 9

def matrix_mult(A, B):
    k = len(A)
    C = [[0]*k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            val = 0
            for t in range(k):
                val = (val + A[i][t] * B[t][j]) % MOD
            C[i][j] = val
    return C

def matrix_pow(M, power):
    k = len(M)
    result = [[int(i == j) for j in range(k)] for i in range(k)]
    while power > 0:
        if power & 1:
            result = matrix_mult(result, M)
        M = matrix_mult(M, M)
        power >>= 1
    return result

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = map(int, data)

    # Precompute all valid column states for given n
    states = []
    for mask in range(1 << n):
        valid = True
        for i in range(n):
            if mask & (1 << i):
                # Check knight attacks within same column
                if i+2 < n and (mask & (1 << (i+2))):
                    valid = False
                    break
                if i-2 >= 0 and (mask & (1 << (i-2))):
                    valid = False
                    break
        if valid:
            states.append(mask)

    k = len(states)
    if m == 1:
        print(k % MOD)
        return

    # Build transition matrix
    trans = [[0]*k for _ in range(k)]
    for i, s1 in enumerate(states):
        for j, s2 in enumerate(states):
            valid = True
            for row in range(n):
                if s1 & (1 << row):
                    # Check attacks to adjacent column
                    if row+1 < n and (s2 & (1 << (row+1))):
                        valid = False
                        break
                    if row-1 >= 0 and (s2 & (1 << (row-1))):
                        valid = False
                        break
                if s2 & (1 << row):
                    # Check attacks from adjacent column
                    if row+1 < n and (s1 & (1 << (row+1))):
                        valid = False
                        break
                    if row-1 >= 0 and (s1 & (1 << (row-1))):
                        valid = False
                        break
            if valid:
                trans[i][j] = 1

    # Initial vector (ways for first column)
    vec = [1]*k

    # Multiply by transition matrix (m-1) times
    if m > 1:
        trans_pow = matrix_pow(trans, m-1)
        new_vec = [0]*k
        for i in range(k):
            val = 0
            for j in range(k):
                val = (val + vec[j] * trans_pow[j][i]) % MOD
            new_vec[i] = val
        vec = new_vec

    result = sum(vec) % MOD
    print(result)

if __name__ == "__main__":
