import sys
MOD = 10**9 + 9

# Precompute all valid columns for n=1,2,3,4
# A column is represented as bitmask of length n
# Two columns are compatible if no knight attacks across them

def generate_valid_masks(n):
    """Return list of valid column masks for given n"""
    masks = []
    for mask in range(1 << n):
        # Check no two knights in same column attack vertically
        valid = True
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            # Check knight at position i attacks positions i+2 and i-2
            if i + 2 < n and (mask >> (i + 2)) & 1:
                valid = False
                break
            if i - 2 >= 0 and (mask >> (i - 2)) & 1:
                valid = False
                break
        if valid:
            masks.append(mask)
    return masks

def compatible(mask1, mask2, n):
    """Check if two column masks are compatible (no attacks across columns)"""
    for i in range(n):
        if not (mask1 >> i) & 1:
            continue
        # Knight at (i, col1) attacks positions in col2:
        # (i+1, col2) and (i-1, col2) if they exist
        if i + 1 < n and (mask2 >> (i + 1)) & 1:
            return False
        if i - 1 >= 0 and (mask2 >> (i - 1)) & 1:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    if m == 1:
        # For single column, count all valid masks
        masks = generate_valid_masks(n)
        print(len(masks) % MOD)
        return

    masks = generate_valid_masks(n)
    k = len(masks)

    # Build compatibility matrix
    compat = [[0] * k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            if compatible(masks[i], masks[j], n):
                compat[i][j] = 1

    # DP: dp[col][mask] = ways to fill first col columns ending with mask
    # Convert to matrix exponentiation for large m
    # dp_next = compat * dp_current (as matrix multiplication)

    # Initial vector: ways for first column = 1 for each valid mask
    vec = [1] * k

    # Matrix exponentiation: compat^(m-1) * vec
    def mat_mul(A, B):
        # A: k x k, B: k x k
        k = len(A)
        C = [[0] * k for _ in range(k)]
        for i in range(k):
            for j in range(k):
                total = 0
                for t in range(k):
                    total = (total + A[i][t] * B[t][j]) % MOD
                C[i][j] = total
        return C

    def mat_vec_mul(A, v):
        # A: k x k, v: length k
        k = len(A)
        res = [0] * k
        for i in range(k):
            total = 0
            for j in range(k):
                total = (total + A[i][j] * v[j]) % MOD
            res[i] = total % MOD
        return res

    def mat_pow(mat, power):
        k = len(mat)
        # Initialize result as identity matrix
        result = [[0] * k for _ in range(k)]
        for i in range(k):
            result[i][i] = 1
        base = [row[:] for row in mat]
        while power > 0:
            if power & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            power >>= 1
        return result

    if m > 1:
        mat_exp = mat_pow(compat, m - 1)
        vec = mat_vec_mul(mat_exp, vec)

    answer = sum(vec) % MOD
    print(answer)

