using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; i++) res *= i;
    return res;
}

vector<int> solve(int n, long long m) {
    vector<int> res;
    vector<int> remaining;
    for (int i = 1; i <= n; i++) remaining.push_back(i);

    // For n <= 8, brute force all permutations and filter those with max f(p)
    if (n <= 8) {
        vector<vector<int>> candidates;
        vector<int> perm(n);
        iota(perm.begin(), perm.end(), 1);
        long long max_f = -1;
        do {
            // Compute f(p)
            long long f_val = 0;
            for (int i = 0; i < n; i++) {
                int min_val = perm[i];
                for (int j = i; j < n; j++) {
                    min_val = min(min_val, perm[j]);
                    f_val += min_val;
                }
            }
            if (f_val > max_f) {
                max_f = f_val;
                candidates.clear();
                candidates.push_back(perm);
            } else if (f_val == max_f) {
                candidates.push_back(perm);
            }
        } while (next_permutation(perm.begin(), perm.end()));

        sort(candidates.begin(), candidates.end());
        return candidates[m - 1];
    }

    // For n > 8, use the pattern: max f(p) is achieved by permutations
    // where the sequence is decreasing except possibly the first element.
    // Specifically, the optimal permutations are those where the sequence
    // is [1, 2, ..., k, n, n-1, ..., k+1] for some k (0 <= k <= n).
    // Lexicographic order among these: start with smallest possible prefix.

    // Determine k such that m-th permutation in lex order
    // Count permutations for each k: if k=0: 1 perm (fully decreasing)
    // For k>0: permutations are determined by choosing which k numbers
    // appear in increasing prefix (must include 1 at start).
    // Actually, structure is fixed: increasing prefix then decreasing suffix.
    // So for given k, exactly one permutation.
    // Thus total count = n+1 permutations (k=0..n).
    // Lex order: k from 0 to n gives permutations in increasing lex order.
    // Wait, check examples: n=4, m=8 gives [4,3,2,1] which is k=0.
    // n=4, m=1 gives [1,2,3,4] which is k=4.
    // So lex order is decreasing k from n down to 0.
    // Let's verify with n=3: permutations:
    // k=3: [1,2,3]
    // k=2: [1,3,2]
    // k=1: [2,3,1]
    // k=0: [3,2,1]
    // Lex order: [1,2,3], [1,3,2], [2,3,1], [3,2,1] matches examples.
    // So m-th permutation corresponds to k = n - (m-1).
    // But ensure m is within 1..n+1.

    int k = n - (m - 1);
    if (k < 0) k = 0;
    if (k > n) k = n;

    // Build permutation: first k numbers increasing, then remaining decreasing
    for (int i = 1; i <= k; i++) res.push_back(i);
    for (int i = n; i > k; i--) res.push_back(i);

    return res;
}

