#include <bits/stdc++.h>
using namespace std;

struct Node {
    int max_len; // longest magical subarray length in this segment
    int left_len; // longest magical subarray starting at left boundary
    int right_len; // longest magical subarray ending at right boundary
    int min_val, max_val; // min and max values in this segment
    int first_val, last_val; // first and last values of this segment
    int seg_len; // length of this segment
};

vector<Node> segtree;
vector<int> arr;

Node merge(const Node &left, const Node &right) {
    Node res;
    res.seg_len = left.seg_len + right.seg_len;
    res.min_val = min(left.min_val, right.min_val);
    res.max_val = max(left.max_val, right.max_val);
    res.first_val = left.first_val;
    res.last_val = right.last_val;

    // Calculate left_len: longest magical starting at left boundary
    if (left.left_len == left.seg_len) {
        // Entire left segment is magical, check if we can extend into right
        int left_min = min(left.first_val, left.last_val);
        int left_max = max(left.first_val, left.last_val);
        if (right.first_val >= left_min && right.first_val <= left_max) {
            // Can extend into right's left_len if right's left part is magical
            res.left_len = left.seg_len + min(right.left_len, 1);
        } else {
            res.left_len = left.left_len;
        }
    } else {
        res.left_len = left.left_len;
    }

    // Calculate right_len: longest magical ending at right boundary
    if (right.right_len == right.seg_len) {
        // Entire right segment is magical, check if we can extend into left
        int right_min = min(right.first_val, right.last_val);
        int right_max = max(right.first_val, right.last_val);
        if (left.last_val >= right_min && left.last_val <= right_max) {
            // Can extend into left's right_len if left's right part is magical
            res.right_len = right.seg_len + min(left.right_len, 1);
        } else {
            res.right_len = right.right_len;
        }
    } else {
        res.right_len = right.right_len;
    }

    // Calculate max_len: longest magical subarray anywhere
    res.max_len = max(left.max_len, right.max_len);

    // Check cross-boundary magical subarrays
    // Case 1: left's right part + right's left part
    if (left.last_val >= min(left.last_val, right.first_val) && 
        left.last_val <= max(left.last_val, right.first_val) &&
        right.first_val >= min(left.last_val, right.first_val) &&
        right.first_val <= max(left.last_val, right.first_val)) {
        int cross_len = min(left.right_len, left.seg_len) + min(right.left_len, right.seg_len);
        res.max_len = max(res.max_len, cross_len);
    }

    // Also consider the boundary values themselves
    res.max_len = max(res.max_len, max(res.left_len, res.right_len));

    return res;
}

void build(int node, int l, int r) {
    if (l == r) {
        segtree[node] = {1, 1, 1, arr[l], arr[l], arr[l], arr[l], 1};
        return;
    }
    int mid = (l + r) / 2;
    build(node*2, l, mid);
    build(node*2+1, mid+1, r);
    segtree[node] = merge(segtree[node*2], segtree[node*2+1]);
}

Node query(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return segtree[node];
    int mid = (l + r) / 2;
    if (qr <= mid) return query(node*2, l, mid, ql, qr);
    if (ql > mid) return query(node*2+1, mid+1, r, ql, qr);

    Node left = query(node*2, l, mid, ql, qr);
    Node right = query(node*2+1, mid+1, r, ql, qr);
    return merge(left, right);
}

