int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    // Duplicate array to handle circular wrap-around
    vector<int> B = A;
    B.insert(B.end(), A.begin(), A.end());

    // Precompute prefix ORs for efficient OR queries
    vector<int> prefix_or(2 * N + 1, 0);
    for (int i = 0; i < 2 * N; ++i) {
        prefix_or[i + 1] = prefix_or[i] | B[i];
    }

    // Function to get OR of subarray [l, r] in B (0-indexed)
    auto get_or = [&](int l, int r) -> int {
        return prefix_or[r + 1] ^ prefix_or[l];
    };

    // Binary search on the answer
    int answer = 0;
    for (int bit = 30; bit >= 0; --bit) {
        int candidate = answer | (1 << bit);

        // Check if we can achieve at least candidate
        // DP: dp[i] = max sections ending at position i with AND >= candidate
        vector<int> dp(2 * N, -1e9);
        vector<int> best_prev(2 * N, -1e9);

        // Initialize for first segment starting positions
        for (int start = 0; start < N; ++start) {
            int current_or = 0;
            for (int end = start; end < start + N; ++end) {
                current_or |= B[end];
                if ((current_or & candidate) == candidate) {
                    dp[end] = max(dp[end], 1);
                }
            }
        }

        // Transition: extend segments
        for (int end = 0; end < 2 * N; ++end) {
            if (dp[end] < 0) continue;
            if (dp[end] >= K) {
                // Found valid partition
                answer = candidate;
                break;
            }

            // Try to start next segment after 'end'
            int next_start = end + 1;
            if (next_start >= 2 * N) continue;

            int current_or = 0;
            for (int next_end = next_start; next_end < min(2 * N, next_start + N); ++next_end) {
                current_or |= B[next_end];
                if ((current_or & candidate) == candidate) {
                    dp[next_end] = max(dp[next_end], dp[end] + 1);
                }
            }
        }

        if (answer == candidate) {
            // Continue to next bit
            continue;
        }
    }

    cout << answer << '\n';
    return 0;
}

