    # BFS from start (cell 1) to find distances to all nodes
    dist_from_start = [-1] * (n + 1)
    q = deque([1])
    dist_from_start[1] = 0
    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist_from_start[v] == -1:
                dist_from_start[v] = dist_from_start[u] + 1
                q.append(v)

    # BFS from each iron cell to find distances to all nodes (reverse graph)
    rev_graph = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in graph[u]:
            rev_graph[v].append(u)

    dist_to_iron = [-1] * (n + 1)
    q = deque()
