    for (int i = 0; i < n; i++) {
        cin >> dolls[i];
    }

    // Precompute prefix sums for quick range sum queries
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + dolls[i];
    }

    // DP table: dp[l][r] = min openings to combine dolls[l..r] into valid set(s)
    vector<vector<long long>> dp(n, vector<long long>(n, LLONG_MAX));
    vector<vector<bool>> valid(n, vector<bool>(n, false));

    // Initialize for single dolls
    for (int i = 0; i < n; i++) {
        dp[i][i] = 0;
        valid[i][i] = true;
    }

    // Fill DP for increasing lengths
    for (int len = 2; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            long long sum = prefix[r + 1] - prefix[l];

            // Check if dolls[l..r] can form valid consecutive sets
            // We need to check if we can partition into segments with consecutive sizes
            // This is equivalent to checking if the multiset can be partitioned into
            // groups where each group has sizes 1..m for some m
            // We'll use DP to check this
            vector<bool> canPartition(len + 1, false);
            canPartition[0] = true;

            for (int i = 0; i < len; i++) {
                if (!canPartition[i]) continue;

                // Find the maximum m such that we have all sizes 1..m in dolls[l+i..r]
                vector<bool> present(501, false);
                int maxSize = 0;
                int count = 0;

                for (int j = i; j < len; j++) {
                    int size = dolls[l + j];
                    if (!present[size]) {
                        present[size] = true;
                        count++;
                        maxSize = max(maxSize, size);
                    }

                    // Check if we have exactly sizes 1..maxSize
                    if (count == maxSize) {
                        bool consecutive = true;
                        for (int k = 1; k <= maxSize; k++) {
                            if (!present[k]) {
                                consecutive = false;
                                break;
                            }
                        }
                        if (consecutive) {
                            canPartition[j + 1] = true;
                        }
                    }
                }
            }

            valid[l][r] = canPartition[len];

            if (!valid[l][r]) continue;

            // Try all possible splits
            for (int k = l; k < r; k++) {
                if (dp[l][k] < LLONG_MAX && dp[k + 1][r] < LLONG_MAX) {
                    long long cost = dp[l][k] + dp[k + 1][r] + (prefix[k + 1] - prefix[l]) + (prefix[r + 1] - prefix[k + 1]);
                    dp[l][r] = min(dp[l][r], cost);
                }
            }
        }
    }

