import re

def is_vowel(c, next_c=None):
    """Return True if c is a vowel, considering context."""
    c = c.upper()
    if next_c:
        next_c = next_c.upper()
    if c == 'Y':
        if next_c and next_c in 'AEIOU':
            return False  # Y is consonant when followed by another vowel
        return True
    return c in 'AEIOU'

def count_syllables(word):
    """Count syllables in a word according to the problem rules."""
    # Extract alphabetic part
    alpha_match = re.search(r'^[A-Za-z]+', word)
    if not alpha_match:
        return 1  # Non-alphabetic word has at least 1 syllable
    alpha = alpha_match.group().upper()

    # Handle QU as single consonant
    alpha = re.sub(r'QU', 'Q', alpha)

    # Apply silent E rule
    if len(alpha) >= 2 and alpha[-1] == 'E':
        if len(alpha) >= 3 and alpha[-2] == 'L' and not is_vowel(alpha[-3]):
            pass  # Keep E for 'able' case
        else:
            alpha = alpha[:-1]  # Remove silent E

    # Apply ES rule
    if len(alpha) >= 3 and alpha[-2:] == 'ES':
        if len(alpha) >= 4 and not is_vowel(alpha[-3]) and not is_vowel(alpha[-4]):
            pass  # Keep ES for 'witches' case
        else:
            alpha = alpha[:-2]  # Remove ES

    # Count vowel groups
    count = 0
    i = 0
    while i < len(alpha):
        if is_vowel(alpha[i], alpha[i+1] if i+1 < len(alpha) else None):
            count += 1
            # Skip consecutive vowels in same syllable
            while i < len(alpha) and is_vowel(alpha[i], alpha[i+1] if i+1 < len(alpha) else None):
                i += 1
        else:
            i += 1

    return max(1, count)  # At least 1 syllable

def find_haiku(words):
    """Try to split words into 5-7-5 syllable lines."""
    n = len(words)
    syllable_counts = [count_syllables(w) for w in words]

    # Try all possible splits
    for i in range(1, n):
        for j in range(i+1, n):
            if sum(syllable_counts[:i]) == 5 and \
               sum(syllable_counts[i:j]) == 7 and \
               sum(syllable_counts[j:]) == 5:
                return [
                    ' '.join(words[:i]),
                    ' '.join(words[i:j]),
                    ' '.join(words[j:])
                ]
    return None

def main():
    line = input().rstrip('\n')
    words = line.split(' ')

    haiku = find_haiku(words)
    if haiku:
        for line in haiku:
            print(line)
    else:
        print(line)

if __name__ == "__main__":
    main()

