import math
import heapq

def angle_between(v1, v2):
    """Return angle in degrees between vectors v1 and v2."""
    dot = v1[0]*v2[0] + v1[1]*v2[1]
    norm1 = math.hypot(v1[0], v1[1])
    norm2 = math.hypot(v2[0], v2[1])
    if norm1 == 0 or norm2 == 0:
        return 0.0
    cos_theta = dot / (norm1 * norm2)
    cos_theta = max(-1.0, min(1.0, cos_theta))
    return math.degrees(math.acos(cos_theta))

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    J = int(next(it))
    R = int(next(it))
    D = float(next(it))

    coords = []
    for _ in range(J):
        x = int(next(it))
        y = int(next(it))
        coords.append((x, y))

    adj = [[] for _ in range(J)]
    for _ in range(R):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        dx = coords[b][0] - coords[a][0]
        dy = coords[b][1] - coords[a][1]
        dist = math.hypot(dx, dy)
        adj[a].append((b, dist, (dx, dy)))

    EPS = 1e-9
    MAX_ANGLE = 180.0

    def can_route(max_angle):
        """Check if there exists a path from 0 to J-1 with all turning angles <= max_angle and total distance <= D."""
        dist = [[float('inf')] * J for _ in range(J)]
        dist[0][0] = 0.0
        pq = [(0.0, 0, 0)]  # (distance, current_node, previous_node)

        while pq:
            d, u, prev = heapq.heappop(pq)
            if d > dist[u][prev] + EPS:
                continue
            if u == J - 1:
                if d <= D + EPS:
                    return True
                continue

            for v, road_dist, vec in adj[u]:
                new_dist = d + road_dist
                if new_dist > D + EPS:
                    continue
                if u == 0:
                    angle = 0.0
                else:
                    prev_vec = (coords[u][0] - coords[prev][0], coords[u][1] - coords[prev][1])
                    angle = angle_between(prev_vec, vec)
                if angle <= max_angle + EPS:
                    if new_dist < dist[v][u] - EPS:
                        dist[v][u] = new_dist
                        heapq.heappush(pq, (new_dist, v, u))
        return False

    if not can_route(MAX_ANGLE):
        print("Impossible")
        return

    lo, hi = 0.0, MAX_ANGLE
    for _ in range(60):
        mid = (lo + hi) / 2
        if can_route(mid):
            hi = mid
        else:
            lo = mid
    print(f"{hi:.8f}")

if __name__ == "__main__":
    solve()

