#include <bits/stdc++.h>
using namespace std;

const int MAXN = 105;
const long double EPS = 1e-12;

int N, L;
int a[MAXN][MAXN];
int outdeg[MAXN];
long double prob[MAXN];
long double new_prob[MAXN];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N >> L;
    for (int i = 1; i <= N; i++) {
        outdeg[i] = 0;
        for (int j = 1; j <= N; j++) {
            cin >> a[i][j];
            outdeg[i] += a[i][j];
        }
    }

    // Initialize probability distribution at day 0 (starting at node 1)
    fill(prob, prob + MAXN, 0.0);
    prob[1] = 1.0;

    int answer = -1;

    // Simulate up to L+9 days
    for (int day = 1; day <= L + 9; day++) {
        fill(new_prob, new_prob + MAXN, 0.0);

        // Transition probabilities
        for (int i = 1; i <= N; i++) {
            if (prob[i] == 0.0) continue;

            if (i == N) {
                // Already at B-ville, stay there
                new_prob[N] += prob[i];
            } else {
                // Move to neighbors
                for (int j = 1; j <= N; j++) {
                    if (a[i][j] > 0) {
                        new_prob[j] += prob[i] * ((long double)a[i][j] / outdeg[i]);
                    }
                }
            }
        }

        // Copy new probabilities back
        copy(new_prob, new_prob + MAXN, prob);

        // Check if current day is within window and probability is exactly 95%
        if (day >= L) {
            if (abs(prob[N] - 0.95) < EPS) {
                answer = day;
                break;
            }
        }
    }

    cout << answer << "\n";

    return 0;
}

