    # Find start and den positions
    start = den = None
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'D':
                den = (i, j)

    # Precompute flood times for each cell
    flood_time = [[float('inf')] * C for _ in range(R)]
    q = deque()
    for i in range(R):
        for j in range(C):
            if grid[i][j] == '*':
                flood_time[i][j] = 0
                q.append((i, j, 0))

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        x, y, t = q.popleft()
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C:
                if grid[nx][ny] in '.S' and flood_time[nx][ny] == float('inf'):
                    flood_time[nx][ny] = t + 1
                    q.append((nx, ny, t + 1))

    # BFS for the Painter and hedgehogs
    visited = [[False] * C for _ in range(R)]
    q = deque()
    q.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

