import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Step 1: Build bipartite graph
    adj = [[] for _ in range(n)]
    for i in range(n):
        pi_candidates = []
        for pi in range(1, n+1):
            # sigma = (a_i - pi) mod n, but in 1..n
            sigma = ((a[i] - pi) % n)
            if sigma == 0:
                sigma = n
            pi_candidates.append((pi-1, sigma-1))
        # Filter: sigma must be unique per pi, and both in 1..n
        # Actually we already ensured sigma in 1..n via mod
        # We'll add edge pi->sigma
        for pi_idx, sigma_idx in pi_candidates:
            adj[pi_idx].append(sigma_idx)

    # Step 2: Maximum bipartite matching (Hopcroft-Karp)
    def hopcroft_karp():
        pair_u = [-1]*n
        pair_v = [-1]*n
        dist = [0]*n
        INF = 10**9

        def bfs():
            from collections import deque
            q = deque()
            for u in range(n):
                if pair_u[u] == -1:
                    dist[u] = 0
                    q.append(u)
                else:
                    dist[u] = INF
            d = INF
            while q:
                u = q.popleft()
                if dist[u] < d:
                    for v in adj[u]:
                        if pair_v[v] == -1:
                            d = dist[u] + 1
                        elif dist[pair_v[v]] == INF:
                            dist[pair_v[v]] = dist[u] + 1
                            q.append(pair_v[v])
            return d != INF

        def dfs(u):
            for v in adj[u]:
                if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
            dist[u] = INF
            return False

        matching = 0
        while bfs():
            for u in range(n):
                if pair_u[u] == -1 and dfs(u):
                    matching += 1
        return pair_u, matching

    pair_u, matching = hopcroft_karp()
    if matching != n:
        print("impossible")
        return

    # Step 3: Reconstruct permutations
    pi = [0]*n
    sigma = [0]*n
    for i in range(n):
        pi_val = i+1
        sigma_val = pair_u[i]+1
        pi[i] = pi_val
        sigma[i] = sigma_val

    # Verify (optional but good for debugging)
    for i in range(n):
        if (pi[i] + sigma[i]) % n != a[i] % n:
            # Adjust sigma if needed (should not happen with perfect matching)
            # Find correct sigma
            for s in range(1, n+1):
                if (pi[i] + s) % n == a[i] % n:
                    sigma[i] = s
                    break

    print(' '.join(map(str, pi)))
    print(' '.join(map(str, sigma)))

if __name__ == "__main__":
    solve()

