        for s in range(1, n+1):
            pi = (a[i] - s) % n
            if pi == 0:
                pi = n
            if 1 <= pi <= n:
                adj[i].append(s-1)  # store 0-indexed sigma values

    # Step 2: Maximum bipartite matching using DFS
    match_sigma = [-1] * n  # which position is matched to sigma value j
    match_pos = [-1] * n    # which sigma value is matched to position i

    def dfs(pos, visited):
        for sigma in adj[pos]:
            if not visited[sigma]:
                visited[sigma] = True
                if match_sigma[sigma] == -1 or dfs(match_sigma[sigma], visited):
                    match_pos[pos] = sigma
                    match_sigma[sigma] = pos
                    return True
        return False

    # Find maximum matching
    for i in range(n):
        visited = [False] * n
