def is_k_periodic(s, k):
    n = len(s)
    if n % k != 0:
        return False

    # First substring
    prev = s[:k]

    # Check each subsequent block
    for i in range(k, n, k):
        current = s[i:i+k]
        # Check if current is right-rotation of prev
        if current != prev[-1] + prev[:-1]:
            return False
        prev = current

    return True

def main():
    s = input().strip()
    n = len(s)

    # Try all possible k from 1 to n
    for k in range(1, n + 1):
        if is_k_periodic(s, k):
            print(k)
            return

    # If no k found (shouldn't happen as k=n always works)
    print(n)

if __name__ == "__main__":
    main()

