#include <iostream>
#include <cmath>
using namespace std;

bool is_valid_hack(long long b, long long d) {
    // Check if b ≡ 1 (mod d) or b ≡ -1 (mod d)
    long long b_mod_d = b % d;
    if (b_mod_d == 1 || b_mod_d == d - 1) {
        return true;
    }

    // Check if b^m ≡ 1 (mod d) for some m
    // Since d is prime, we can check if b is a primitive root modulo d
    // Actually, we need to check if order of b modulo d exists
    // For prime d, order divides d-1
    long long order = d - 1;
    long long temp = order;

    // Factorize d-1 to find possible orders
    for (long long p = 2; p * p <= temp; p++) {
        if (temp % p == 0) {
            // Check if b^(order/p) ≡ 1 (mod d)
            long long exp = order / p;
            long long result = 1;
            long long base = b % d;
            // Modular exponentiation
            while (exp > 0) {
                if (exp & 1) result = (result * base) % d;
                base = (base * base) % d;
                exp >>= 1;
            }
            if (result == 1) {
                order /= p;
                while (temp % p == 0) temp /= p;
            }
        }
    }
    if (temp > 1) {
        long long exp = order / temp;
        long long result = 1;
        long long base = b % d;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % d;
            base = (base * base) % d;
            exp >>= 1;
        }
        if (result == 1) order /= temp;
    }

    // Now order is the multiplicative order of b modulo d
    // We need to check if there exists m such that d divides (b^m - 1) or (b^m + 1)
    // Actually, the condition is: exists m such that d | (b^m - 1) or d | (b^m + 1)
    // Since d is prime, this is equivalent to b^m ≡ ±1 (mod d)

    // Check if b^order ≡ 1 (mod d)
    long long result = 1;
    long long base = b % d;
    long long exp = order;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % d;
        base = (base * base) % d;
        exp >>= 1;
    }

    if (result == 1) {
        // Check all divisors of order
        for (long long m = 1; m * m <= order; m++) {
            if (order % m == 0) {
                // Check m
                long long pow_m = 1;
                base = b % d;
                exp = m;
                while (exp > 0) {
                    if (exp & 1) pow_m = (pow_m * base) % d;
                    base = (base * base) % d;
                    exp >>= 1;
                }
                if (pow_m == 1 || pow_m == d - 1) return true;

                // Check order/m
                if (m != order / m) {
                    long long pow_m2 = 1;
                    base = b % d;
                    exp = order / m;
                    while (exp > 0) {
                        if (exp & 1) pow_m2 = (pow_m2 * base) % d;
                        base = (base * base) % d;
                        exp >>= 1;
                    }
                    if (pow_m2 == 1 || pow_m2 == d - 1) return true;
                }
            }
        }
    }

    return false;
}

